-- Generated by generate-views.ts from public.campaign. Regenerate after a migration changes its columns.
CREATE OR REPLACE VIEW goodparty_data_catalog.gp_api_mirror_dms.campaign
COMMENT 'Current state of public.campaign: the latest change per primary key in dms_cdc_change, deletes removed. TOASTable columns an update left out are carried from the previous change.'
AS
WITH reload AS (
  SELECT max(reloaded_at) AS reloaded_at FROM goodparty_data_catalog.gp_api_mirror_dms.dms_cdc_reload WHERE source_table = 'campaign'
),
changes AS (
  SELECT c.pk, c.op, c.seq, c.ingested_at, c.row_image, CASE WHEN c.op = 'update' THEN json_object_keys(c.row_image) END AS image_columns
  FROM goodparty_data_catalog.gp_api_mirror_dms.dms_cdc_change c CROSS JOIN reload r
  WHERE c.source_schema = 'public' AND c.source_table = 'campaign'
    AND (r.reloaded_at IS NULL OR c.ingested_at >= r.reloaded_at)
),
latest AS (
  SELECT
    max_by(op, seq) AS _dms_op,
    max(ingested_at) AS _dms_ingested_at,
    max_by(CAST(row_image:['id']::string AS INT), seq) AS `id`,
    max_by(CAST(row_image:['created_at']::string AS TIMESTAMP_NTZ), seq) AS `created_at`,
    max_by(CAST(row_image:['updated_at']::string AS TIMESTAMP_NTZ), seq) AS `updated_at`,
    max_by(row_image:['slug']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'slug') THEN seq END) AS `slug`,
    max_by(CAST(row_image:['is_active']::string AS BOOLEAN), seq) AS `is_active`,
    max_by(CAST(row_image:['is_verified']::string AS BOOLEAN), seq) AS `is_verified`,
    max_by(CAST(row_image:['is_pro']::string AS BOOLEAN), seq) AS `is_pro`,
    max_by(CAST(row_image:['is_demo']::string AS BOOLEAN), seq) AS `is_demo`,
    max_by(CAST(row_image:['did_win']::string AS BOOLEAN), seq) AS `did_win`,
    max_by(CAST(row_image:['date_verified']::string AS TIMESTAMP_NTZ), seq) AS `date_verified`,
    max_by(row_image:['tier']::string, seq) AS `tier`,
    max_by(row_image:['data']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'data') THEN seq END) AS `data`,
    max_by(row_image:['details']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'details') THEN seq END) AS `details`,
    max_by(row_image:['ai_content']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'ai_content') THEN seq END) AS `ai_content`,
    max_by(row_image:['vendor_ts_data']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'vendor_ts_data') THEN seq END) AS `vendor_ts_data`,
    max_by(CAST(row_image:['user_id']::string AS INT), seq) AS `user_id`,
    max_by(row_image:['completed_task_ids']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'completed_task_ids') THEN seq END) AS `completed_task_ids`,
    max_by(row_image:['formatted_address']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'formatted_address') THEN seq END) AS `formatted_address`,
    max_by(row_image:['place_id']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'place_id') THEN seq END) AS `place_id`,
    max_by(CAST(row_image:['can_download_federal']::string AS BOOLEAN), seq) AS `can_download_federal`,
    max_by(CAST(row_image:['has_free_texts_offer']::string AS BOOLEAN), seq) AS `has_free_texts_offer`,
    max_by(CAST(row_image:['free_texts_offer_redeemed_at']::string AS TIMESTAMP_NTZ), seq) AS `free_texts_offer_redeemed_at`,
    max_by(row_image:['organization_slug']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'organization_slug') THEN seq END) AS `organization_slug`,
    max_by(row_image:['campaign_email']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'campaign_email') THEN seq END) AS `campaign_email`,
    max_by(row_image:['primary_result']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'primary_result') THEN seq END) AS `primary_result`,
    max_by(row_image:['ballot_status']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'ballot_status') THEN seq END) AS `ballot_status`,
    max_by(row_image:['signup_goal']::string, CASE WHEN op <> 'update' OR array_contains(image_columns, 'signup_goal') THEN seq END) AS `signup_goal`
  FROM changes
  GROUP BY pk
)
SELECT `id`, `created_at`, `updated_at`, `slug`, `is_active`, `is_verified`, `is_pro`, `is_demo`, `did_win`, `date_verified`, `tier`, `data`, `details`, `ai_content`, `vendor_ts_data`, `user_id`, `completed_task_ids`, `formatted_address`, `place_id`, `can_download_federal`, `has_free_texts_offer`, `free_texts_offer_redeemed_at`, `organization_slug`, `campaign_email`, `primary_result`, `ballot_status`, `signup_goal`, _dms_ingested_at
FROM latest
WHERE _dms_op <> 'delete';
